--
-- Table structure for table `borrow_records`
--

DROP TABLE IF EXISTS `borrow_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `borrow_records` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `request_number` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `borrower_user_id` bigint unsigned NOT NULL,
  `borrower_email` varchar(256) COLLATE utf8mb4_unicode_ci NOT NULL,
  `borrower_name` varchar(256) COLLATE utf8mb4_unicode_ci NOT NULL,
  `borrower_unit_id` bigint unsigned DEFAULT NULL,
  `borrower_dept_id` bigint unsigned DEFAULT NULL,
  `borrow_type` enum('new_inventory','tools_equipment','deposited_tools','others') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'new_inventory',
  `deposit_record_id` bigint unsigned DEFAULT NULL,
  `others_detail` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `purpose` text COLLATE utf8mb4_unicode_ci,
  `remark` text COLLATE utf8mb4_unicode_ci,
  `borrow_date` date NOT NULL,
  `period_days` smallint unsigned NOT NULL DEFAULT '7',
  `planned_return_date` date NOT NULL,
  `actual_return_date` date DEFAULT NULL,
  `requires_acknowledge` tinyint(1) NOT NULL DEFAULT '0',
  `acknowledge_user_id` bigint unsigned DEFAULT NULL,
  `acknowledge_email` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `acknowledge_name` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `acknowledged_at` timestamp NULL DEFAULT NULL,
  `approver_user_id` bigint unsigned DEFAULT NULL,
  `approver_email` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `approver_name` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL,
  `warehouse_staff_user_id` bigint unsigned DEFAULT NULL,
  `warehouse_staff_name` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `taken_at` timestamp NULL DEFAULT NULL,
  `returned_at` timestamp NULL DEFAULT NULL,
  `return_remarks` text COLLATE utf8mb4_unicode_ci,
  `admin_notes` text COLLATE utf8mb4_unicode_ci,
  `borrower_return_date` date DEFAULT NULL,
  `borrower_return_ack` tinyint(1) NOT NULL DEFAULT '0',
  `wh_return_ack` tinyint(1) NOT NULL DEFAULT '0',
  `status` enum('draft','acknowledged','approved','active','overdue','returned','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `cancel_reason` text COLLATE utf8mb4_unicode_ci,
  `extension_status` enum('none','pending','approved','rejected') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `extension_reason` text COLLATE utf8mb4_unicode_ci,
  `extension_proposed_date` date DEFAULT NULL,
  `extension_requested_by` bigint unsigned DEFAULT NULL,
  `extension_requested_at` timestamp NULL DEFAULT NULL,
  `extension_decided_by` bigint unsigned DEFAULT NULL,
  `extension_decided_at` timestamp NULL DEFAULT NULL,
  `created_by` bigint unsigned DEFAULT NULL,
  `updated_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `deleted_reason` text COLLATE utf8mb4_unicode_ci,
  `deleted_by` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `borrow_records_request_number_unique` (`request_number`),
  KEY `borrow_records_status_planned_return_date_index` (`status`,`planned_return_date`),
  KEY `borrow_records_borrower_user_id_status_index` (`borrower_user_id`,`status`),
  KEY `borrow_records_approver_user_id_status_index` (`approver_user_id`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=50 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

