INSERT INTO `equipment_inspections` VALUES (1,1,2,NULL,NULL,'2026-07-02 00:00:00',NULL,'fail',33,'[{\"note\": \"\", \"label\": \"ບໍ່ ມີ ຮອຍ ຕັດ/ຂາດ/ດຶງ ເສັ້ນໃຍ\", \"status\": \"fail\"}, {\"note\": \"\", \"label\": \"ບໍ່ ມີ ຄວາມ ເສຍຫาย ຈาก ຄວາມ ຮ້ອນ/ສານ ເຄມີ\", \"status\": \"pass\"}, {\"note\": \"\", \"label\": \"ຮອຍ ຫຍິບ (stitching) ຄົບ, ບໍ່ ຫລຸດ\", \"status\": \"fail\"}, {\"note\": \"ປ້າຍອ່ານບໍ່ແຈ້ງ ບໍ່ມີຜົນຕໍ່ການໂຫຼດນໍ້າໜັກ\", \"label\": \"ປ້າຍ SWL/ນ້ຳໜັກ ຮັບ ໄດ້ ຍັງ ອ່ານ ໄດ້ ຊັດ\", \"status\": \"na\"}, {\"note\": \"ປົກກະຕິ ບໍ່ແຕກ ບໍ່ບິດບ້ຽວ\", \"label\": \"ຫ່ວງ/ຕະຂໍ/shackle ບໍ່ ບິດ ບ້ຽວ/ບໍ່ ແຕກ\", \"status\": \"pass\"}, {\"note\": \"\", \"label\": \"ບໍ່ ມີ ຮອຍ ເປື້ອນ ນ້ຳມັນ/ຂີ້ ໝ້ຽງ ຫຼາຍ ເກີນ\", \"status\": \"fail\"}, {\"note\": \"\", \"label\": \"ຢູ່ ໃນ ໄລຍະ ກວດ ປະຈຳ ປີ (ບໍ່ ໝົດ ອາຍຸ)\", \"status\": \"fail\"}]',NULL,'2026-07-02',NULL,NULL,1,'2026-07-01 21:03:33','2026-07-02 01:25:32'),(2,2,5,'engine',NULL,'2026-07-03 14:40:46','SA','follow_up',79,'[{\"note\": \"ມີຮອຍແຕກແຫງ\", \"label\": \"ງ່າມ-ງາ, ເສົາຍົກ, ແຜງຮັບສິນຄ້າ (Forks, Mast & Load Backrest)\", \"status\": \"fail\"}, {\"note\": \"ມີນໍ້າມັນຊຶມ ຢູ່ປາຍຫົວທໍ່\", \"label\": \"ລະບົບ ໄຮໂດຼລິກ / ບໍ່ ມີ ຮົ່ວ (Hydraulic System — Leakage)\", \"status\": \"fail\"}, {\"note\": \"ຂອບຕີນລໍ້ມີຮອຍແຕກ\", \"label\": \"ຢາງ ແລະ ລໍ້ (Tyres & Wheels)\", \"status\": \"fail\"}, {\"note\": \"\", \"label\": \"ລະບົບ ບັງຄັບ ລ້ຽວ (Steering System)\", \"status\": \"pass\"}, {\"note\": \"\", \"label\": \"ເບກ ແລະ ເບກ ຈອດ (Brake & Parking Brake)\", \"status\": \"pass\"}, {\"note\": \"\", \"label\": \"ແກ, ໄຟ ແລະ ສຽງ ຖອຍ ຫຼັງ (Horn, Lights & Reverse Alarm)\", \"status\": \"pass\"}, {\"note\": \"\", \"label\": \"ສາຍ ຄາດ ນິລະໄພ ແລະ ບ່ອນ ນັ່ງ (Seat Belt & Operator Seat)\", \"status\": \"pass\"}, {\"note\": \"\", \"label\": \"ຫຼັງຄາ ກັນ ຕົກ ແລະ ປ້າຍ ຄວາມ ປອດໄພ (Overhead Guard & Safety Labels)\", \"status\": \"pass\"}, {\"note\": \"\", \"label\": \"ໜ້າປັດ ແລະ ໄຟ ເຕືອນ (Dashboard & Warning Indicators)\", \"status\": \"pass\"}, {\"note\": \"\", \"label\": \"ນ້ຳມັນ ເຄື່ອງ ແລະ ນ້ຳມັນ ເຊື້ອ ໄຟ (Engine Oil & Fuel)\", \"status\": \"pass\"}, {\"note\": \"\", \"label\": \"ນ້ຳ ຫລໍ່ ເຢັນ ແລະ ໝໍ້ ນ້ຳ (Coolant & Radiator)\", \"status\": \"pass\"}, {\"note\": \"\", \"label\": \"ການ ຮົ່ວ ນ້ຳມັນ/LPG ແລະ ທໍ່ ໄອ ເສຍ (Fuel/LPG Leakage & Exhaust)\", \"status\": \"pass\"}, {\"note\": \"\", \"label\": \"ຟັງຊັນ ເຄື່ອນ ທີ່, ຍົກ ແລະ ອຽງ (Travel, Lift & Tilt Function)\", \"status\": \"pass\"}, {\"note\": \"\", \"label\": \"ສະພາບ ໂດຍ ລວມ (Overall Condition)\", \"status\": \"pass\"}]',NULL,NULL,'equipment/inspections/2/ins_6a4875e3a2a89.jpg','[\"equipment/inspections/2/ins_6a4875e3a2a89.jpg\"]',1,'2026-07-03 07:40:46','2026-07-03 20:06:53'),(3,3,NULL,NULL,NULL,'2026-07-04 00:45:51','SA','follow_up',NULL,NULL,'ທົດສອບ','2026-07-04',NULL,NULL,1,'2026-07-03 17:45:51','2026-07-03 17:45:51'),(4,2,7,'ev','pre_use','2026-07-06 07:15:21','SA','pass',100,'[{\"note\": \"ປົກະຕິດີ\", \"label\": \"ງ່າມ, ເສົາ ຍົກ ແລະ ແຜງ ຮັບ ສິນຄ້າ (Forks, Mast & Load Backrest)\", \"status\": \"na\"}, {\"note\": \"ປົກະຕິດີ\", \"label\": \"ລະບົບ ໄຮໂດຼລິກ / ບໍ່ ມີ ຮົ່ວ (Hydraulic System — Leakage)\", \"status\": \"na\"}, {\"note\": \"ປົກະຕິດີ\", \"label\": \"ຢາງ ແລະ ລໍ້ (Tyres & Wheels)\", \"status\": \"na\"}, {\"note\": \"ປົກະຕິດີ\", \"label\": \"ລະບົບ ບັງຄັບ ລ້ຽວ (Steering System)\", \"status\": \"na\"}, {\"note\": \"ປົກະຕິດີ\", \"label\": \"ເບກ ແລະ ເບກ ຈອດ (Brake & Parking Brake)\", \"status\": \"na\"}, {\"note\": \"ປົກະຕິດີ\", \"label\": \"ແກ, ໄຟ ແລະ ສຽງ ຖອຍ ຫຼັງ (Horn, Lights & Reverse Alarm)\", \"status\": \"na\"}, {\"note\": \"ປົກະຕິດີ\", \"label\": \"ສາຍ ຄາດ ນິລະໄພ ແລະ ບ່ອນ ນັ່ງ (Seat Belt & Operator Seat)\", \"status\": \"na\"}, {\"note\": \"ປົກະຕິດີ\", \"label\": \"ຫຼັງຄາ ກັນ ຕົກ ແລະ ປ້າຍ ຄວາມ ປອດໄພ (Overhead Guard & Safety Labels)\", \"status\": \"na\"}, {\"note\": \"ປົກະຕິດີ\", \"label\": \"ໜ້າ ປັດ ແລະ ໄຟ ເຕືອນ (Dashboard & Warning Indicators)\", \"status\": \"na\"}, {\"note\": \"ປົກະຕິດີ\", \"label\": \"ແບັດເຕີຣີ ແລະ ຂົ້ວ ຕໍ່ (Battery & Connector)\", \"status\": \"na\"}, {\"note\": \"ປົກະຕິດີ\", \"label\": \"ຟັງຊັນ ເຄື່ອນ ທີ່, ຍົກ ແລະ ອຽງ (Travel, Lift & Tilt Function)\", \"status\": \"na\"}, {\"note\": \"ປົກະຕິດີ\", \"label\": \"ສະພາບ ໂດຍ ລວມ (Overall Condition)\", \"status\": \"na\"}]',NULL,'2026-07-06',NULL,NULL,1,'2026-07-06 00:15:21','2026-07-06 00:15:21');
