  `model` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `serial_number` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `quantity` int unsigned NOT NULL DEFAULT '0',
