  KEY `inventory_items_location_id_index` (`location_id`),
  FULLTEXT KEY `inventory_items_name_description_brand_category_fulltext` (`name`,`description`,`brand`,`category`)
) ENGINE=InnoDB AUTO_INCREMENT=17166 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
