--
-- Table structure for table `material_price_history`
--

DROP TABLE IF EXISTS `material_price_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `material_price_history` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `material_id` bigint unsigned NOT NULL,
  `unit_price` decimal(15,2) DEFAULT NULL,
  `currency` enum('LAK','THB','USD') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `contract_number` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `contract_date` date DEFAULT NULL,
  `update_date` date NOT NULL,
  `updated_by` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `material_price_history_material_id_update_date_index` (`material_id`,`update_date`),
  CONSTRAINT `material_price_history_material_id_foreign` FOREIGN KEY (`material_id`) REFERENCES `materials` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=367 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

